    <header><p class="font-mono text-sm font-bold text-[#2F64A8]">#{{ candidate.rank }} · {{ candidate.symbol }}</p><h3 class="mt-1 text-lg font-bold">{{ candidate.name }}</h3><p class="mt-1 text-xs text-slate-500">{{ candidate.sector }}</p></header>
    <section class="mt-4"><h4 class="text-sm font-bold">{{ bank ? 'Dasar penyertaan data' : 'Mengapa perusahaan ini dipilih' }}</h4><p class="mt-2 text-sm leading-6 text-slate-600">{{ bank ? `Data ${candidate.symbol} tersedia pada ${candidate.financialPeriod || 'periode yang tersedia'} dan disajikan sesuai urutan market cap provider.` : candidate.whySelected }}</p></section>
