    <dl class="mt-4 grid grid-cols-2 gap-3 text-xs leading-5"><div><dt class="text-slate-500">Periode keuangan</dt><dd>{{ candidate.financialPeriod || 'Tidak tersedia' }}</dd></div><div><dt class="text-slate-500">Harga per tanggal</dt><dd>{{ candidate.priceAsOf || 'Tidak tersedia' }}</dd></div><div><dt class="text-slate-500">Asal data</dt><dd>{{ candidate.sourceOrigin || 'Tidak tersedia' }}</dd></div><div><dt class="text-slate-500">Diambil</dt><dd>{{ candidate.providerSource?.retrievedAt || 'Tidak tersedia' }}</dd></div></dl>
